"""Inputs and pinned outputs for the upstream Embench PicoJPEG decoder."""

from __future__ import annotations

import base64
import hashlib
from collections.abc import Mapping

from .common import profiled_parameters

_IMAGES = {
    "grayscale": "",
    "color-444": "",
    "color-420": "",
}
_EXPECTED = {
    "658a1bc1ba62f066d4c79dbaa791ab166edf6fc81b3b5367f5220531534f3f29": bytes.fromhex(
        "5815a6df270bafec"
    ),
    "2156cd419882aef35459c99feb3d76da9ba0b2c3b58076183aaf07a86f768e8e": bytes.fromhex(
        "8ce033fd5cf73611"
    ),
    "9ce2cdfed2bbbb57f2ad72e39a8f8503bdef0099ec660b1321f85dc14638600d": bytes.fromhex(
        "d811167584c1e632"
    ),
}


def input_for(values: Mapping[str, object]) -> bytes:
    _, profile = profiled_parameters(
        values, (), ("grayscale", "color-444", "color-420")
    )
    return base64.b64decode(_IMAGES[profile], validate=True)


def output_for(data: bytes) -> bytes:
    try:
        return _EXPECTED[hashlib.sha256(data).hexdigest()]
    except KeyError:
        raise ValueError("picojpeg input is not an authored case") from None
